import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { Theme, Track } from '../types'
import {
  EQ_ROWS,
  FRAME_MS,
  FRAME_ROWS,
  INFO_SCRIPT,
  KNOB_COLS,
  KNOB_IDLE,
  KNOB_ROWS,
  NOW_SCRIPT,
  THEME_DEFAULT,
  THEME_RANGE,
  TIME_COLS,
  beatMs,
  emptySpectrum,
  eqCells,
  explainFailure,
  hex,
  isQuiet,
  knobCells,
  layout,
  palette,
  parseInfo,
  parseLevels,
  parseNowPlaying,
  parseTheme,
  seedOf,
  stepSpectrum,
  themeFrom,
  themeText,
  timeCells,
} from './lib'
import type { Layout } from './lib'

const track = atom({ plugin: 'clauisc', key: 'track' } as const, null)
const isHidden = atom({ plugin: 'clauisc', key: 'isHidden' } as const, false)
const problem = atom({ plugin: 'clauisc', key: 'problem' } as const, null)
// /clauisc theme and /clauisc width: the console's look, kept in $.store too.
const theme = atom({ plugin: 'clauisc', key: 'theme' } as const, null)
const volume = atom({ plugin: 'clauisc', key: 'volume' } as const, null)

const POLL_MS = 2000
// An absolute path: apps that start Claude Code may give it a bare PATH.
const OSASCRIPT = '/usr/bin/osascript'
// Long enough for the person to answer macOS's first "control Music?" prompt,
// which holds osascript until it is answered.
const INFO_TIMEOUT_MS = 60000
// Repaint the knobs and the time every this many EQ frames.
const KNOB_EVERY = 5
// Live levels older than this are stale: the EQ falls back to the beat.
const LEVELS_FRESH_MS = 500

// Module state for polling and the animation only; what the band draws lives in $.state.
const live = {
  current: null as Track | null,
  polledAt: 0,
  source: 'none yet',
  spectrum: emptySpectrum(0),
  wasQuiet: false,
  look: THEME_DEFAULT as Theme,
  at: null as Layout | null,
  volume: null as number | null,
  bandId: null as string | null,
  hasFrame: false,
  isPolling: false,
  poller: null as Timer | null,
  animator: null as Timer | null,
  // Diagnostics for /clauisc status.
  polls: 0,
  ticks: 0,
  frames: 0,
  watchdogPolls: 0,
  renders: 0,
  surface: null as string | null,
  lastExit: null as number | null,
  nowPlayingExit: null as number | null,
  nowPlayingStdout: '',
  nowPlayingStderr: '',
  lastStdout: '',
  lastStderr: '',
  lastError: null as string | null,
  // The live EQ: audio/clauisc-levels, the system audio's bands.
  audio: 'off' as 'off' | 'starting' | 'live' | 'failed',
  audioReason: '',
  audioRun: 0,
  levels: null as number[] | null,
  levelsAt: 0,
  levelLines: 0,
  // Resolves once the current run of the helper is capturing or has failed.
  settle: () => {},
}

/** Waits until the helper is capturing or has said why not, at most `ms`. */
function settled($: EngineInterface, ms: number): Promise<void> {
  if (live.audio !== 'starting') return Promise.resolve()
  return new Promise<void>(resolve => {
    live.settle = resolve
    $.clock.after(ms, resolve)
  })
}

/** The audio helper's path: built by audio/build.sh, git-ignored. */
const levelsBinary = ($: EngineInterface) => `${$.plugin.root.replace(/\/\.claude-plugin\/?$/, '')}/audio/clauisc-levels`

/**
 * Runs the audio helper and keeps its latest levels until it ends or a newer
 * run starts; a stop ends the stream, which closes the helper's output.
 */
async function listen($: EngineInterface) {
  const run = ++live.audioRun
  live.audio = 'starting'
  live.audioReason = ''
  live.levels = null
  try {
    let rest = ''
    for await (const { stream, text } of $.process.spawn({ argv: [levelsBinary($)] })) {
      if (run !== live.audioRun) return
      if (stream === 'stderr') {
        live.audioReason = text.trim().slice(0, 200) || live.audioReason
        continue
      }
      const lines = (rest + text).split('\n')
      rest = lines.pop() ?? ''
      for (const line of lines) {
        const said = parseLevels(line)
        if (!said) continue
        if (said.kind === 'ready') live.audio = 'live'
        else if (said.kind === 'error') {
          live.audio = 'failed'
          live.audioReason = said.reason
          live.settle()
        } else {
          live.audio = 'live'
          live.levels = said.levels
          live.levelsAt = await $.clock.now()
          live.levelLines += 1
        }
        if (live.audio === 'live') live.settle()
      }
    }
    if (run === live.audioRun && live.audio !== 'failed') {
      live.audio = 'failed'
      live.audioReason ||= 'the audio helper exited'
    }
  } catch (error) {
    if (run !== live.audioRun) return
    live.audio = 'failed'
    live.audioReason = /ENOENT|not found|no such file/i.test(String(error))
      ? `not built yet: run ${levelsBinary($).replace(/clauisc-levels$/, 'build.sh')}`
      : String(error).slice(0, 200)
  } finally {
    if (run === live.audioRun) {
      live.levels = null
      live.settle()
    }
  }
}

function stopListening() {
  live.audioRun += 1
  live.audio = 'off'
  live.levels = null
}

/** System Now Playing first: it describes streamed songs that Music's AppleScript cannot. */
async function pollNowPlaying($: EngineInterface): Promise<boolean> {
  const ran = await $.process.run(
    [OSASCRIPT, '-l', 'JavaScript', '-e', NOW_SCRIPT],
    { timeoutMs: INFO_TIMEOUT_MS },
  )
  live.nowPlayingExit = ran.exitCode
  live.nowPlayingStdout = ran.stdout.trim().slice(0, 300)
  live.nowPlayingStderr = ran.stderr.trim().slice(0, 300)
  const found = ran.exitCode === 0 ? parseNowPlaying(ran.stdout) : null
  if (!found) return false

  live.source = 'system Now Playing'
  live.current = found.track
  if (found.volume !== live.volume) {
    live.volume = found.volume
    await update($, volume, () => found.volume)
  }
  await update($, problem, () => null)
  await update($, track, () => found.track)
  return true
}

/** Music's own AppleScript: the fallback when Now Playing is unreadable. */
async function pollMusic($: EngineInterface) {
  const ran = await $.process.run([OSASCRIPT, '-e', INFO_SCRIPT], { timeoutMs: INFO_TIMEOUT_MS })
  live.source = 'Music AppleScript'
  live.lastExit = ran.exitCode
  live.lastStdout = ran.stdout.trim().slice(0, 300)
  live.lastStderr = ran.stderr.trim().slice(0, 300)
  const now = ran.exitCode === 0 ? parseInfo(ran.stdout) : null
  live.current = now
  await update($, problem, () => (ran.exitCode === 0 ? null : explainFailure(ran.stderr)))
  await update($, track, () => now)
}

async function poll($: EngineInterface) {
  if (live.isPolling) return
  live.isPolling = true
  live.polls += 1
  try {
    if (!(await pollNowPlaying($))) await pollMusic($)
    live.polledAt = await $.clock.now()
    live.lastError = null
  } catch (error) {
    // osascript could not start or ran past the timeout: say so and keep trying.
    live.polledAt = await $.clock.now()
    live.lastError = String(error).slice(0, 300)
    await update($, problem, () => `Could not run osascript: ${live.lastError}`)
  } finally {
    live.isPolling = false
  }
}

/** Seconds into the track, counting the time since the last poll while playing. */
function elapsed(t: Track, now: number): number {
  const since = t.isPlaying && live.polledAt ? (now - live.polledAt) / 1000 : 0
  return t.position + since
}

function progress(t: Track, now: number): number {
  return t.duration > 0 ? elapsed(t, now) / t.duration : 0
}

async function statusReport($: EngineInterface): Promise<string> {
  const t = live.current
  const age = live.polledAt ? Math.round(((await $.clock.now()) - live.polledAt) / 1000) : null
  return [
    'Clauisc status',
    `- source: ${live.source}`,
    `- polls: ${live.polls} (timer ticks ${live.ticks}, EQ frames ${live.frames}, backup polls ${live.watchdogPolls}), last ${age === null ? 'never' : `${age}s ago`}`,
    `- last error: ${live.lastError ?? 'none'}`,
    `- Now Playing: exit ${live.nowPlayingExit ?? 'not run'}, stdout ${JSON.stringify(live.nowPlayingStdout)}, stderr ${JSON.stringify(live.nowPlayingStderr)}`,
    `- Music AppleScript: exit ${live.lastExit ?? 'not run'}, stdout ${JSON.stringify(live.lastStdout)}, stderr ${JSON.stringify(live.lastStderr)}`,
    `- track: ${t ? `${t.isPlaying ? 'playing' : 'paused'} "${t.name}" by ${t.artist || 'unknown'} at ${Math.round(t.position)}/${Math.round(t.duration)}s (bpm ${t.bpm})` : 'none'}`,
    `- volume: ${live.volume ?? 'unknown'}`,
    `- theme: ${themeText(live.look)}`,
    `- EQ: ${live.audio === 'live' ? `live audio (${live.levelLines} level lines)` : live.audio === 'off' ? 'drawn from the beat (/clauisc audio on for the real sound)' : `${live.audio}${live.audioReason ? `: ${live.audioReason}` : ''}; drawn from the beat`}`,
    `- band drawn: ${live.renders} times, surface ${live.surface ?? 'never asked'}`,
  ].join('\n')
}

/** One EQ frame; every few frames the knobs and the time too. */
async function frame($: EngineInterface) {
  live.frames += 1
  const now = await $.clock.now()
  // A backup for the poll timer: if it has gone quiet, ask Now Playing from here.
  if (!live.isPolling && now - live.polledAt > POLL_MS * 2) {
    live.watchdogPolls += 1
    void poll($)
  }
  const t = live.current
  const at = live.at
  if (!t || !live.bandId || !live.hasFrame || !at) return
  const requestId = live.bandId
  const seed = seedOf(t.id)
  live.spectrum = stepSpectrum(
    live.spectrum,
    at,
    // No BPM: a groove of the track's own, 90 to 130.
    {
      ms: elapsed(t, now) * 1000,
      beat: beatMs(t.bpm || 90 + Math.round(seed * 40), 0),
      seed,
      isPlaying: t.isPlaying,
      levels: live.levels && now - live.levelsAt < LEVELS_FRESH_MS ? live.levels : null,
    },
    live.look,
    Math.random,
  )
  // Paused and settled: nothing moves, so nothing to repaint.
  const quiet = isQuiet(live.spectrum)
  if (!(quiet && live.wasQuiet)) {
    $.ui.blit({ requestId, key: 'eq', cells: eqCells(live.spectrum, at, live.look) }).catch(() => undefined)
  }
  live.wasQuiet = quiet
  if (live.frames % KNOB_EVERY === 0) {
    const lit = t.isPlaying ? palette(live.look).glow : KNOB_IDLE
    $.ui.blit({ requestId, key: 'seek', cells: knobCells(progress(t, now), lit) }).catch(() => undefined)
    $.ui.blit({ requestId, key: 'time', cells: timeCells(elapsed(t, now), t.duration, live.look) }).catch(() => undefined)
  }
}

async function setTheme($: EngineInterface, next: Theme | null) {
  if (next) await $.store.set('theme', next)
  else await $.store.delete('theme')
  await update($, theme, () => next)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'clauisc',
      description:
        'Toggle the Apple Music console; "status", "audio on|off", "theme k=v…", "width <n>"',
    })
    const saved = await $.store.get('theme').catch(() => undefined)
    if (saved && typeof saved === 'object') {
      await update($, theme, () => themeFrom(saved))
    } else {
      // A width set before themes existed carries over.
      const width = await $.store.get('width').catch(() => undefined)
      if (typeof width === 'number') await update($, theme, () => themeFrom({ width }))
    }
    if ((await $.store.get('audio').catch(() => undefined)) === true) void listen($)
    void poll($)
    live.poller?.cancel()
    live.poller = $.clock.every(POLL_MS, () => {
      live.ticks += 1
      void poll($)
    })
    live.animator?.cancel()
    live.animator = $.clock.every(FRAME_MS, () => {
      void frame($)
    })

    return next(e)
  })

  on('command.run', { command: 'clauisc' }, async ($, e) => {
    const arg = e.args.trim()
    const [word = '', ...rest] = arg.split(/\s+/)
    const now = themeFrom(await read($, theme))
    const [lo, hi] = THEME_RANGE.width
    switch (word.toLowerCase()) {
      case 'width': {
        const value = rest[0]?.toLowerCase()
        if (value === undefined) {
          return { text: `Clauisc frame width: ${now.width} (default ${THEME_DEFAULT.width}). Set it with /clauisc width <${lo}-${hi}> or /clauisc width reset.` }
        }
        if (value === 'reset') {
          await setTheme($, { ...now, width: THEME_DEFAULT.width })
          return { text: `Clauisc frame width reset to ${THEME_DEFAULT.width}.` }
        }
        const n = Number(value)
        if (!Number.isInteger(n) || n < lo || n > hi) {
          return { text: `Clauisc: width must be a whole number from ${lo} to ${hi}.` }
        }
        await setTheme($, { ...now, width: n })
        return { text: `Clauisc frame width set to ${n}.` }
      }
      case 'theme': {
        if (rest.length === 0) {
          return { text: `Clauisc theme: ${themeText(now)}\nChange it with /clauisc theme hue=120 gain=90 …, or /clauisc theme reset. The preview (bun preview/server.ts) builds this line for you.` }
        }
        if (rest[0]?.toLowerCase() === 'reset') {
          await setTheme($, null)
          return { text: `Clauisc theme reset: ${themeText(THEME_DEFAULT)}` }
        }
        const next = parseTheme(rest.join(' '), now)
        if (typeof next === 'string') return { text: `Clauisc: ${next}.` }
        await setTheme($, next)
        return { text: `Clauisc theme set: ${themeText(next)}` }
      }
      case 'audio': {
        const value = rest[0]?.toLowerCase()
        if (value === 'on') {
          await $.store.set('audio', true)
          stopListening()
          void listen($)
          // Long enough for the helper to start or to say why it cannot.
          await settled($, 3000)
          return {
            text:
              live.audio === 'failed'
                ? `Clauisc live EQ failed: ${live.audioReason}. If macOS blocked it, allow your terminal under System Settings → Privacy & Security → Screen & System Audio Recording, restart it, and run /clauisc audio on again.`
                : 'Clauisc live EQ on: the bars follow the system audio.',
          }
        }
        if (value === 'off') {
          await $.store.set('audio', false)
          stopListening()
          return { text: 'Clauisc live EQ off: the bars follow the beat.' }
        }
        return { text: `Clauisc EQ: ${live.audio}${live.audioReason ? ` (${live.audioReason})` : ''}. /clauisc audio on follows the system audio (asks for Screen & System Audio Recording); off draws it from the beat.` }
      }
      case 'status':
        await poll($)
        return { text: await statusReport($) }
      default: {
        const hidden = await update($, isHidden, was => !was)
        return { text: hidden ? 'Clauisc band hidden.' : 'Clauisc band shown.' }
      }
    }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    live.renders += 1
    live.surface = e.surface
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)
    const t = await read($, track)
    const cols = e.props.bodyColumns

    if (t === null) {
      const why = await read($, problem)
      if (!why) return next(e)
      const { Box, Text } = $.ui.resolve(e)
      return (
        <Box justifyContent="flex-end" width={cols}>
          <Text color="#d97757" wrap="wrap">
            ♪ Clauisc: {why}
          </Text>
        </Box>
      )
    }

    const look = themeFrom(await read($, theme))
    const vol = await read($, volume)
    const at = layout(look, cols)
    live.look = look
    live.at = at
    const hasFrame = e.surface === 'terminal' && e.props.maxRows >= FRAME_ROWS + 2 && at !== null
    live.hasFrame = hasFrame

    if (!hasFrame || !at) {
      // Too small, or a surface without Rasters: one line of text.
      const status = t.isPlaying ? '▶' : '⏸'
      const { Box, Text } = $.ui.resolve(e)
      return (
        <Box justifyContent="flex-end" width={cols}>
          <Text wrap="truncate-end">
            {status} {t.name}{t.artist ? ` · ${t.artist}` : ''}
          </Text>
        </Box>
      )
    }

    // The head unit: top edge, a side each way and the bottom. Inside, the
    // volume gauge, the display (track over the EQ) and the progress gauge.
    live.bandId = e.requestId
    const { Box, Text, Raster } = $.ui.resolve(e)
    const now = await $.clock.now()
    const colors = palette(look)
    const screen = hex(colors.screen)
    const lit = t.isPlaying ? colors.glow : KNOB_IDLE
    const titleCols = at.display - 6 - TIME_COLS - 1
    const side = (
      <Box flexDirection="column">
        {Array.from({ length: FRAME_ROWS }, () => (
          <Text dimColor>|</Text>
        ))}
      </Box>
    )
    const knob = (key: string, value: number | null, label: string) => (
      <Box flexDirection="column" width={KNOB_COLS}>
        <Raster key={key} columns={KNOB_COLS} rows={KNOB_ROWS} cells={knobCells(value, lit)} />
        <Text dimColor>{label}</Text>
      </Box>
    )

    return (
      <Box flexDirection="row" justifyContent="flex-end" alignItems="flex-start" width={cols}>
        <Box flexDirection="column">
          <Text dimColor>{` ${'_'.repeat(at.inner)}`}</Text>
          <Box flexDirection="row" alignItems="flex-start">
            {side}
            <Box flexDirection="column" width={at.inner}>
              <Box flexDirection="row" alignItems="flex-start">
                <Box marginLeft={1}>{knob('volume', vol === null ? null : vol / 100, ' VOL ')}</Box>
                <Box flexDirection="column" marginLeft={2} width={at.display} backgroundColor={screen}>
                  <Box flexDirection="row" width={at.display} backgroundColor={screen}>
                    <Text color={hex(colors.label)} backgroundColor={screen}>
                      {t.isPlaying ? ' PLAY ' : ' PAUSE'}
                    </Text>
                    <Box width={titleCols} backgroundColor={screen}>
                      <Text color={hex(colors.glow)} backgroundColor={screen} bold wrap="truncate-end">
                        {` ${t.name}${t.artist ? ` · ${t.artist}` : ''}`}
                      </Text>
                    </Box>
                    <Raster key="time" columns={TIME_COLS} rows={1} cells={timeCells(elapsed(t, now), t.duration, look)} />
                    <Text backgroundColor={screen}> </Text>
                  </Box>
                  <Raster key="eq" columns={at.display} rows={EQ_ROWS} cells={eqCells(live.spectrum, at, look)} />
                </Box>
                <Box marginLeft={2} marginRight={1}>{knob('seek', progress(t, now), 'SEEK ')}</Box>
              </Box>
            </Box>
            {side}
          </Box>
          <Text dimColor>{`\`${'-'.repeat(at.inner)}'`}</Text>
        </Box>
      </Box>
    )
  })
}

