import type { Theme, Track } from '../types'

export type { Theme, Track }

// The console, inside its frame: a gauge knob each side of the display.
export const KNOB_COLS = 5
export const KNOB_ROWS = 3
/** Columns each side of the display: a pad, the knob and a gap. */
export const SIDE_COLS = 1 + KNOB_COLS + 2
/** The display: one row of text over the EQ, two rows of bars and their band labels. */
export const BAR_ROWS = 2
export const EQ_ROWS = BAR_ROWS + 1
export const DISPLAY_ROWS = 1 + EQ_ROWS
/** Rows inside the frame: the knobs and the display. */
export const FRAME_ROWS = DISPLAY_ROWS
/** The time readout at the display's top right, "12:34/56:07". */
export const TIME_COLS = 11
export const BANDS = ['BASS', 'LOW', 'MID', 'VOX', 'HIGH', 'AIR'] as const

const DEFAULT = 0x01000000

const SEP = '\u001f'

/** AppleScript printing the player state and current track, fields split by U+001F. */
export const INFO_SCRIPT = `
if application "Music" is not running then return "stopped"
tell application "Music"
  set stateText to player state as string
  if stateText is "stopped" then return "stopped"
  set {trackKey, trackName, trackArtist, trackAlbum, trackBpm, trackLength} to {"", "", "", "", 0, 0}
  set {trackKind, trackProblem} to {"", ""}
  try
    set nowTrack to current track
    try
      set trackKind to (class of nowTrack) as string
    end try
    try
      set trackKey to persistent ID of nowTrack
    end try
    try
      set trackName to name of nowTrack
    end try
    try
      set trackArtist to artist of nowTrack
    end try
    try
      set trackAlbum to album of nowTrack
    end try
    try
      set trackBpm to bpm of nowTrack
    end try
    try
      set trackLength to duration of nowTrack
    end try
  on error errorText number errorNumber
    set trackProblem to (errorNumber as string) & " " & errorText
  end try
  if trackName is "" then
    try
      set trackName to current stream title
    end try
  end if
  set playhead to 0
  try
    set playhead to player position
  end try
  set sep to character id 31
  return stateText & sep & trackKey & sep & trackName & sep & trackArtist & sep & trackAlbum & sep & trackBpm & sep & playhead & sep & trackLength & sep & trackKind & sep & trackProblem
end tell
`

/**
 * JXA reading macOS's system Now Playing info (what Control Center shows),
 * which also describes streamed Apple Music songs that Music's AppleScript
 * cannot, and the system output volume. Prints JSON for parseNowPlaying.
 *
 * Now Playing carries metadata only (title, artist, album, times, rate,
 * artwork): no audio levels, so the console's EQ is drawn from the beat.
 */
export const NOW_SCRIPT = `
ObjC.import('Foundation');
function run() {
  var volume = null;
  try {
    var app = Application.currentApplication();
    app.includeStandardAdditions = true;
    var v = app.getVolumeSettings().outputVolume;
    if (typeof v === 'number') volume = v;
  } catch (e) {}
  $.NSBundle.bundleWithPath('/System/Library/PrivateFrameworks/MediaRemote.framework/').load;
  var request = $.NSClassFromString('MRNowPlayingRequest');
  if (request.isNil()) return JSON.stringify({ error: 'MRNowPlayingRequest is unavailable' });
  var item = request.localNowPlayingItem;
  if (item.isNil()) return JSON.stringify({ state: 'stopped', volume: volume });
  var info = item.nowPlayingInfo;
  if (info.isNil()) return JSON.stringify({ state: 'stopped', volume: volume });
  function raw(key) { return info.objectForKey('kMRMediaRemoteNowPlayingInfo' + key); }
  function get(key) { var value = raw(key); return value.isNil() ? null : ObjC.unwrap(value); }
  var rate = Number(get('PlaybackRate') || 0);
  var elapsed = Number(get('ElapsedTime') || 0);
  var stamp = raw('Timestamp');
  var since = stamp.isNil() ? 0 : -stamp.timeIntervalSinceNow;
  return JSON.stringify({
    state: rate > 0 ? 'playing' : 'paused',
    id: String(get('UniqueIdentifier') || get('ContentItemIdentifier') || ''),
    title: get('Title') || '',
    artist: get('Artist') || '',
    album: get('Album') || '',
    position: elapsed + rate * since,
    duration: Number(get('Duration') || 0),
    volume: volume,
  });
}
`

const num = (s: string | undefined) => {
  const n = parseFloat((s ?? '').trim().replace(',', '.'))
  return Number.isFinite(n) ? n : 0
}

export function parseInfo(stdout: string): Track | null {
  // AppleScript spells an absent value "missing value" when it joins text.
  const f = stdout
    .replace(/\n$/, '')
    .split(SEP)
    .map(field => (field.trim() === 'missing value' ? '' : field))
  if (f.length < 8 || (f[0] !== 'playing' && f[0] !== 'paused')) return null
  const name = f[2] ?? ''
  const artist = f[3] ?? ''
  if (!name && !artist) {
    // Paused with nothing loaded: nothing to show.
    if (f[0] !== 'playing') return null
    // Playing, but Music describes no track (often a streamed song): still show the band.
    return {
      isPlaying: true,
      id: 'undescribed',
      name: 'Playing in Music',
      artist: 'Music shares no track details',
      album: '',
      bpm: 0,
      position: num(f[6]),
      duration: num(f[7]),
    }
  }
  return {
    isPlaying: f[0] === 'playing',
    id: f[1] || `${name}|${artist}`,
    name: name || 'Unknown track',
    artist,
    album: f[4] ?? '',
    bpm: num(f[5]),
    position: num(f[6]),
    duration: num(f[7]),
  }
}

/**
 * What NOW_SCRIPT reports, parsed: the track, or null when nothing is playing,
 * and the system output volume (0..100), null when the output has none.
 */
export type NowPlaying = { track: Track | null; volume: number | null }

/**
 * NOW_SCRIPT's JSON as a track; null when it is not Now Playing JSON at all
 * (the caller then falls back to Music's AppleScript).
 */
export function parseNowPlaying(stdout: string): NowPlaying | null {
  let raw: Record<string, unknown>
  try {
    raw = JSON.parse(stdout.trim()) as Record<string, unknown>
  } catch {
    return null
  }
  if (typeof raw !== 'object' || raw === null || typeof raw.error === 'string') return null
  const text = (key: string) => (typeof raw[key] === 'string' ? (raw[key] as string) : '')
  const number = (key: string) => (typeof raw[key] === 'number' && Number.isFinite(raw[key]) ? (raw[key] as number) : 0)
  const state = text('state')
  const name = text('title')
  const artist = text('artist')
  const hasTrack = (state === 'playing' || state === 'paused') && (name !== '' || artist !== '')
  return {
    track: hasTrack
      ? {
          isPlaying: state === 'playing',
          id: text('id') || `${name}|${artist}`,
          name: name || 'Unknown track',
          artist,
          album: text('album'),
          bpm: 0,
          position: number('position'),
          duration: number('duration'),
        }
      : null,
    volume: typeof raw.volume === 'number' && Number.isFinite(raw.volume) ? raw.volume : null,
  }
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Little-endian u32 words as standard padded base64, the Raster's `cells`. */
export function encode(words: number[]): string {
  const bytes = new Uint8Array(Uint32Array.from(words).buffer)
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i]! << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += B64[(n >> 18) & 63]! + B64[(n >> 12) & 63]!
    out += i + 1 < bytes.length ? B64[(n >> 6) & 63]! : '='
    out += i + 2 < bytes.length ? B64[n & 63]! : '='
  }
  return out
}

/** Milliseconds per beat: the track's beat when it has a BPM, else a loose random groove. */
export function beatMs(bpm: number, random: number): number {
  if (bpm > 0) {
    let ms = 60000 / bpm
    while (ms < 300) ms *= 2
    while (ms > 1200) ms /= 2
    return ms
  }
  return 380 + random * 320
}

/** A string hashed to 0..1: gives each track its own groove on the EQ. */
export function seedOf(text: string): number {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return (h >>> 0) / 4294967296
}

// Theme: what /clauisc theme and the preview's sliders set.

export const THEME_DEFAULT: Theme = { width: 64, hue: 32, gain: 100, decay: 5, gap: 1, peaks: 1, ghost: 1 }

export const THEME_RANGE: { readonly [K in keyof Theme]: readonly [number, number] } = {
  width: [46, 200],
  hue: [0, 359],
  gain: [50, 150],
  decay: [1, 9],
  gap: [0, 1],
  peaks: [0, 1],
  ghost: [0, 1],
}

export const THEME_KEYS = Object.keys(THEME_DEFAULT) as (keyof Theme)[]

/** Any stored value as a Theme: known keys kept, clamped and rounded; the rest the defaults. */
export function themeFrom(raw: unknown): Theme {
  const theme = { ...THEME_DEFAULT }
  if (typeof raw !== 'object' || raw === null) return theme
  for (const key of THEME_KEYS) {
    const value = (raw as Record<string, unknown>)[key]
    if (typeof value !== 'number' || !Number.isFinite(value)) continue
    const [lo, hi] = THEME_RANGE[key]
    theme[key] = Math.max(lo, Math.min(hi, Math.round(value)))
  }
  return theme
}

/** `hue=120 gain=90` applied over `base`, or a message naming what is wrong. */
export function parseTheme(args: string, base: Theme): Theme | string {
  const next: Record<string, number> = { ...base }
  for (const pair of args.trim().split(/\s+/).filter(Boolean)) {
    const [key, value] = pair.split('=')
    if (!key || !(THEME_KEYS as string[]).includes(key)) {
      return `unknown setting "${key ?? pair}"; use ${THEME_KEYS.join(', ')}`
    }
    const n = Number(value)
    const [lo, hi] = THEME_RANGE[key as keyof Theme]
    if (value === undefined || value === '' || !Number.isInteger(n) || n < lo || n > hi) {
      return `${key} must be a whole number from ${lo} to ${hi}`
    }
    next[key] = n
  }
  return themeFrom(next)
}

/** A theme as /clauisc theme takes it. */
export const themeText = (theme: Theme) => THEME_KEYS.map(key => `${key}=${theme[key]}`).join(' ')

// Colors.

/** An HSL color as 0xRRGGBB; `s` and `l` in percent. */
export function hsl(h: number, s: number, l: number): number {
  const hue = (((h % 360) + 360) % 360) / 60
  const sat = s / 100
  const lum = l / 100
  const c = (1 - Math.abs(2 * lum - 1)) * sat
  const x = c * (1 - Math.abs((hue % 2) - 1))
  const [r, g, b] = [[c, x, 0], [x, c, 0], [0, c, x], [0, x, c], [x, 0, c], [c, 0, x]][Math.floor(hue) % 6]!
  const m = lum - c / 2
  const byte = (v: number) => Math.round((v + m) * 255)
  return (byte(r!) << 16) | (byte(g!) << 8) | byte(b!)
}

export const hex = (color: number) => `#${color.toString(16).padStart(6, '0')}`

export type Palette = {
  /** Lit segments and text. */
  glow: number
  /** The top row of the bars and the peaks. */
  hot: number
  /** Unlit segments. */
  ghost: number
  /** The display's glass. */
  screen: number
  /** Band labels and the PLAY tag. */
  label: number
}

export function palette(theme: Theme): Palette {
  return {
    glow: hsl(theme.hue, 100, 60),
    hot: hsl(theme.hue - 30, 100, 62),
    ghost: hsl(theme.hue, 50, 12),
    screen: hsl(theme.hue, 40, 5),
    label: hsl(theme.hue, 55, 42),
  }
}

export const KNOB_IDLE = 0x8a8a8a
const KNOB_SCALE = 0x444444
const KNOB_POINTER = 0xf0f0f0

// Layout.

/** Narrowest display that still fits the PLAY tag, ten columns of title and the time. */
export const MIN_DISPLAY = 30

export type Layout = {
  /** Inside width of the frame. */
  inner: number
  /** Width of the display between the knobs. */
  display: number
  /** Each bar's column within the display, left to right. */
  barAt: number[]
  /** Each bar's band, an index into BANDS. */
  bandOf: number[]
  /** Each bar's sub-band in the live levels: SUB_BANDS of each band, low to high. */
  subOf: number[]
  /** Each band's label and its column within the display. */
  labels: { col: number; text: string }[]
}

/** Where everything sits for `theme` in `columns` of terminal; null when the console does not fit. */
export function layout(theme: Theme, columns: number): Layout | null {
  const inner = Math.min(theme.width, columns - 3)
  const display = inner - 2 * SIDE_COLS
  if (display < MIN_DISPLAY) return null
  const step = theme.gap ? 2 : 1
  const count = theme.gap ? Math.floor((display + 1) / 2) : display
  const offset = Math.floor((display - ((count - 1) * step + 1)) / 2)
  const barAt = Array.from({ length: count }, (_, i) => offset + i * step)
  const bandOf = barAt.map((_, i) => Math.min(BANDS.length - 1, Math.floor((i * BANDS.length) / count)))
  const subOf = bandOf.map((band, i) => {
    const first = bandOf.indexOf(band)
    const size = bandOf.lastIndexOf(band) - first + 1
    return band * SUB_BANDS + Math.floor(((i - first) * SUB_BANDS) / size)
  })
  const labels = BANDS.map((name, band) => {
    const first = barAt[bandOf.indexOf(band)]!
    const last = barAt[bandOf.lastIndexOf(band)]!
    const text = name.slice(0, last - first + 1)
    return { col: first + Math.floor((last - first + 1 - text.length) / 2), text }
  })
  return { inner, display, barAt, bandOf, subOf, labels }
}

// The EQ. Now Playing shares no audio, so without the live levels of
// audio/clauisc-levels each band is drawn from the beat: the kick in BASS and
// LOW, phrases in VOX, off-beat hats in HIGH and AIR.

/** Live levels per band: clauisc-levels prints BANDS.length * SUB_BANDS of them. */
export const SUB_BANDS = 4

/** What clauisc-levels says on one line. */
export type LevelsLine = { kind: 'ready' } | { kind: 'levels'; levels: number[] } | { kind: 'error'; reason: string }

export function parseLevels(line: string): LevelsLine | null {
  const [word, ...rest] = line.trim().split(' ')
  if (word === 'R') return { kind: 'ready' }
  if (word === 'E') return { kind: 'error', reason: rest.join(' ') || 'the audio helper failed' }
  if (word !== 'L' || rest.length !== BANDS.length * SUB_BANDS) return null
  const levels = rest.map(Number)
  return levels.every(Number.isFinite) ? { kind: 'levels', levels: levels.map(v => Math.max(0, Math.min(1, v))) } : null
}

/** Milliseconds between EQ frames. */
export const FRAME_MS = 90

export type Spectrum = { levels: number[]; peaks: number[]; holds: number[] }

export const emptySpectrum = (bars: number): Spectrum => ({
  levels: Array(bars).fill(0),
  peaks: Array(bars).fill(0),
  holds: Array(bars).fill(0),
})

/** How loud `band` is `ms` into the groove, 0..1 before gain. */
export function bandLevel(band: number, ms: number, beat: number, seed: number, noise: number): number {
  const phase = (ms % beat) / beat
  const kick = Math.exp(-6 * phase)
  const hat = Math.exp(-9 * ((phase * 2) % 1)) * (phase >= 0.5 ? 1 : 0.45)
  const phrase = Math.max(0, Math.sin((2 * Math.PI * ms) / (beat * 8) + seed * 2 * Math.PI))
  switch (band) {
    case 0: return 0.3 + 0.66 * kick
    case 1: return 0.28 + 0.42 * kick + 0.18 * noise
    case 2: return 0.4 + 0.2 * Math.sin(ms / 700 + seed * 9) + 0.18 * noise
    case 3: return 0.18 + 0.55 * phrase + 0.15 * noise
    case 4: return 0.16 + 0.48 * hat + 0.14 * noise
    default: return 0.1 + 0.28 * hat * noise + 0.12 * noise
  }
}

/**
 * One EQ frame: each bar jumps up to its band's level and falls back at the
 * theme's decay; peaks hold a moment, then fall. Paused, everything falls.
 * With `levels` (the live audio's sub-bands) the bars show those instead.
 */
export function stepSpectrum(
  spectrum: Spectrum,
  at: Layout,
  input: { ms: number; beat: number; seed: number; isPlaying: boolean; levels?: readonly number[] | null },
  theme: Theme,
  random: () => number,
): Spectrum {
  const count = at.barAt.length
  const was = spectrum.levels.length === count ? spectrum : emptySpectrum(count)
  const fall = 0.012 * theme.decay
  const next = emptySpectrum(count)
  for (let i = 0; i < count; i++) {
    const heard = input.levels?.[at.subOf[i]!]
    const level = !input.isPlaying
      ? 0
      : heard !== undefined
        ? heard * (theme.gain / 100)
        : bandLevel(at.bandOf[i]!, input.ms, input.beat, input.seed, random()) * (0.85 + 0.3 * random()) * (theme.gain / 100)
    const now = Math.max(0, Math.min(1, Math.max(level, was.levels[i]! - fall)))
    next.levels[i] = now
    if (now >= was.peaks[i]!) {
      next.peaks[i] = now
      next.holds[i] = 8
    } else if (was.holds[i]! > 0) {
      next.peaks[i] = was.peaks[i]!
      next.holds[i] = was.holds[i]! - 1
    } else {
      next.peaks[i] = Math.max(now, was.peaks[i]! - 0.03)
    }
  }
  return next
}

export const isQuiet = (spectrum: Spectrum) => spectrum.levels.every(v => v === 0) && spectrum.peaks.every(v => v === 0)

const BLOCK = 0x2580 // + 1..8: lower eighths, ▁ to █
const PEAK = 0x2594 // ▔, the upper eighth

/** The EQ, `display` x EQ_ROWS cells: BAR_ROWS of bars in eighths, then the band labels. */
export function eqCells(spectrum: Spectrum, at: Layout, theme: Theme): string {
  const colors = palette(theme)
  const unlit = theme.ghost ? colors.ghost : colors.screen
  const units = BAR_ROWS * 8
  const words: number[] = []
  const barOf = new Map(at.barAt.map((col, i) => [col, i]))
  for (let row = 0; row < BAR_ROWS; row++) {
    // Row 0 is the top; each row holds 8 eighths of the bar.
    const below = (BAR_ROWS - 1 - row) * 8
    for (let col = 0; col < at.display; col++) {
      const bar = barOf.get(col)
      if (bar === undefined) {
        words.push(0x20, colors.screen, colors.screen)
        continue
      }
      const lit = Math.max(0, Math.min(8, Math.round((spectrum.levels[bar] ?? 0) * units) - below))
      const fg = row === 0 ? colors.hot : colors.glow
      const peak = Math.round((spectrum.peaks[bar] ?? 0) * units) - below
      if (lit > 0) words.push(BLOCK + lit, fg, unlit)
      else if (theme.peaks && peak > 0 && peak <= 8) words.push(PEAK, colors.hot, unlit)
      else words.push(0x20, unlit, unlit)
    }
  }
  const labels = Array<number>(at.display).fill(0x20)
  for (const { col, text } of at.labels) {
    for (let i = 0; i < text.length; i++) labels[col + i] = text.charCodeAt(i)
  }
  for (const glyph of labels) words.push(glyph, colors.label, colors.screen)
  return encode(words)
}

// The knobs: a braille dial, its scale swept from seven to five o'clock and
// lit up to the value, with a pointer from the middle.

const BRAILLE_BIT = [
  [0x01, 0x08],
  [0x02, 0x10],
  [0x04, 0x20],
  [0x40, 0x80],
]

const KNOB_CX = (KNOB_COLS * 2 - 1) / 2
const KNOB_CY = (KNOB_ROWS * 4 - 1) / 2
const SWEEP = 135

const KNOB_SCALE_DOTS: { x: number; y: number; at: number }[] = (() => {
  const dots: { x: number; y: number; at: number }[] = []
  for (let y = 0; y < KNOB_ROWS * 4; y++) {
    for (let x = 0; x < KNOB_COLS * 2; x++) {
      if (Math.abs(Math.hypot(x - KNOB_CX, y - KNOB_CY) - 4) > 0.55) continue
      // Degrees clockwise from twelve o'clock.
      const angle = (Math.atan2(x - KNOB_CX, KNOB_CY - y) * 180) / Math.PI
      if (Math.abs(angle) <= SWEEP + 5) dots.push({ x, y, at: (angle + SWEEP) / (2 * SWEEP) })
    }
  }
  return dots
})()

/**
 * A knob, KNOB_COLS x KNOB_ROWS cells, turned to `value` (0..1): the scale lit
 * in `color` up to it and a pointer at it; `null` draws it unlit, pointerless.
 * A cell shows one color: the pointer's, else the lit scale's, else the scale's.
 */
export function knobCells(value: number | null, color: number): string {
  const cells = Array.from({ length: KNOB_COLS * KNOB_ROWS }, () => ({ bits: 0, rank: 0 }))
  const mark = (x: number, y: number, rank: number) => {
    if (x < 0 || y < 0 || x >= KNOB_COLS * 2 || y >= KNOB_ROWS * 4) return
    const cell = cells[Math.floor(y / 4) * KNOB_COLS + Math.floor(x / 2)]!
    cell.bits |= BRAILLE_BIT[y % 4]![x % 2]!
    cell.rank = Math.max(cell.rank, rank)
  }
  const v = value === null ? null : Math.max(0, Math.min(1, value))
  for (const dot of KNOB_SCALE_DOTS) mark(dot.x, dot.y, v !== null && dot.at <= v ? 2 : 1)
  if (v !== null) {
    const angle = ((-SWEEP + 2 * SWEEP * v) * Math.PI) / 180
    for (const r of [1.2, 2.1, 2.9]) {
      mark(Math.round(KNOB_CX + r * Math.sin(angle)), Math.round(KNOB_CY - r * Math.cos(angle)), 3)
    }
  }
  const colors = [DEFAULT, KNOB_SCALE, color, KNOB_POINTER]
  const words: number[] = []
  for (const cell of cells) {
    if (cell.bits) words.push(0x2800 + cell.bits, colors[cell.rank]!, DEFAULT)
    else words.push(0x20, DEFAULT, DEFAULT)
  }
  return encode(words)
}

/** Seconds as m:ss. */
export function clockText(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

/** The time readout, TIME_COLS x 1 cells, right-aligned: "1:23/3:40". */
export function timeCells(position: number, duration: number, theme: Theme): string {
  const colors = palette(theme)
  const text = (duration > 0 ? `${clockText(Math.min(position, duration))}/${clockText(duration)}` : clockText(position))
    .slice(-TIME_COLS)
    .padStart(TIME_COLS)
  const words: number[] = []
  for (const glyph of text) words.push(glyph.charCodeAt(0), colors.glow, colors.screen)
  return encode(words)
}

/** A one-line, actionable reading of osascript's error output. */
export function explainFailure(stderr: string): string {
  if (/-1743|not authori[sz]ed|Not allowed to send Apple events/i.test(stderr)) {
    return 'macOS is blocking access to Music. Allow your terminal app under System Settings → Privacy & Security → Automation → Music, then restart it.'
  }
  if (/-1728|-1708/.test(stderr)) return 'Music has no current track it can describe.'
  const line = stderr.trim().split('\n').pop() ?? ''
  return line ? `osascript failed: ${line.slice(0, 160)}` : 'osascript failed without saying why.'
}

